      <table><thead><tr><th>编号 / 名称</th><th>阶段</th><th>暂停状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in iterations" :key="row.reference.id"><td>{{ row.body.number }} / {{ row.body.name }}</td><td>{{ label(row.body.iteration?.stage || '') }}</td><td>{{ label(row.body.iteration?.holdState || '') }}</td><td><button :disabled="locked" @click="open(row.reference.id)">打开迭代</button></td></tr></tbody></table>
