      <label>本次操作原因<textarea v-model="reason" aria-label="操作原因" maxlength="8000" :disabled="locked" /></label>
      <div v-if="projectDraft || plan || taskDraft" class="lookup"><label>查找成员<input v-model="memberSearch" aria-label="成员搜索" maxlength="256" /></label><button :disabled="busy" @click="findMembers">查找成员</button><p>当前选定成员会保留；搜索不会替换已有成员。</p></div>
      <form v-if="projectDraft" @submit.prevent="saveProject"><fieldset :disabled="locked || !(current ? can('edit') && current.body.project?.definition.ownerId === scope?.actorId : can('add'))">
