        <ul><li v-for="id in projectDraft.members" :key="id">{{ memberName(id) }} <button type="button" :disabled="id === projectDraft.ownerId" @click="projectDraft.members = projectDraft.members.filter(x => x !== id)">移除成员</button></li></ul>
