      <section v-if="work"><h3>迭代执行</h3><p>{{ label(work.stage) }} · {{ label(work.holdState) }} · 工作进度 {{ current?.progress?.percent === null ? '暂无计划任务' : `${current?.progress?.percent}%` }}</p>
