        <h3>计划任务</h3><button v-if="can('edit')" :disabled="locked || work.holdState === 'HELD'" @click="newTask">添加计划任务</button>
        <article v-for="task in work.tasks" :key="task.plan.id"><h4>{{ task.plan.title }}</h4><p>{{ label(task.state) }} · 权重 {{ task.plan.weight }} · 负责人 {{ memberName(task.plan.ownerId) }} · 确认者 {{ memberName(task.plan.confirmerId) }}</p><p>判据：{{ task.plan.acceptance }}</p><p v-if="task.confirmedAt">已由 {{ memberName(task.confirmedBy || '') }} 于 {{ task.confirmedAt }} 确认。</p>
          <ul><li v-for="d in task.deliverables" :key="d.id">文档 {{ d.id }} · 准确版本 {{ d.version }}</li></ul>
          <button v-if="task.deliverables.length" :disabled="busy" @click="inspectDeliverables(task.deliverables)">查看准确交付物</button>
          <template v-if="['TODO', 'IN_PROGRESS', 'BLOCKED'].includes(task.state)"><button v-if="can('edit')" :disabled="locked || work.holdState === 'HELD'" @click="taskDraft = copy(task.plan)">编辑任务计划</button><button v-if="can('edit')" :disabled="locked || work.holdState === 'HELD'" @click="command('CANCEL_TASK', { taskId: task.plan.id })">取消计划任务</button>
            <template v-if="task.plan.ownerId === scope?.actorId && work.stage === 'IN_DESIGN'"><button v-if="can('edit')" :disabled="locked || work.holdState === 'HELD'" @click="command('START_TASK', { taskId: task.plan.id })">开始任务</button><button v-if="can('edit')" :disabled="locked || work.holdState === 'HELD'" @click="command('BLOCK_TASK', { taskId: task.plan.id })">标记阻塞</button><button v-if="can('task-submit')" :disabled="locked || work.holdState === 'HELD'" @click="submitTaskId = task.plan.id; deliverables = []">选择交付物</button></template>
          </template><button v-if="can('task-confirm') && task.state === 'SUBMITTED' && task.plan.confirmerId === scope?.actorId" :disabled="locked || work.holdState === 'HELD'" @click="command('CONFIRM_TASK', { taskId: task.plan.id })">核对交付物并确认</button>
          <button v-if="can('task-confirm') && task.state === 'SUBMITTED' && task.plan.confirmerId === scope?.actorId" :disabled="locked || work.holdState === 'HELD'" @click="command('RETURN_TASK', { taskId: task.plan.id })">退回补充交付</button>
        </article>
        <section v-if="reviewDocuments.length"><h4>准确交付原件</h4><article v-for="d in reviewDocuments" :key="d.reference.id"><h5>{{ d.body.name }} · 版本 {{ d.reference.version }}</h5><p>来源：{{ d.body.source.ownerName }} / {{ d.body.source.organization }} / {{ d.body.source.sourceVersion }}</p><p>来源依据：{{ d.body.source.acquisitionBasis }}</p><ul><li v-for="content in d.body.contents" :key="content.occurrenceId">{{ d.contentStatus.find(x => x.occurrenceId === content.occurrenceId)?.fileName }} · {{ content.language }} <button :disabled="busy" @click="download(d, content.occurrenceId)">下载准确原件</button></li></ul></article></section>
        <form v-if="taskDraft" @submit.prevent="saveTask"><fieldset :disabled="locked || work.holdState === 'HELD'"><label>任务标题<input v-model="taskDraft.title" aria-label="任务标题" required /></label><label>负责人<select v-model="taskDraft.ownerId" aria-label="任务负责人"><option v-for="id in projectMembers" :key="id" :value="id">{{ memberName(id) }}</option></select></label><label>独立确认者<select v-model="taskDraft.confirmerId" aria-label="任务确认者"><option value="">请选择另一位成员</option><option v-for="id in projectMembers.filter(x => x !== taskDraft?.ownerId)" :key="id" :value="id">{{ memberName(id) }}</option></select></label><label>明确权重<input v-model="taskDraft.weight" aria-label="任务权重" inputmode="decimal" required /></label><label>截止日期<input v-model="taskDraft.dueDate" aria-label="任务截止" type="date" required /></label><label>交付判据<textarea v-model="taskDraft.acceptance" aria-label="任务判据" required /></label><button>保存任务计划</button></fieldset></form>
        <section v-if="submitTaskId"><h4>选取准确文档交付物</h4><label>查找文档<input v-model="documentSearch" aria-label="文档搜索" maxlength="256" /></label><button :disabled="busy" @click="findDocuments(1)">查找文档</button><button :disabled="busy || documentPage === 1" @click="findDocuments(documentPage - 1)">上一页文档</button><button :disabled="busy || documentChoices.length < 20" @click="findDocuments(documentPage + 1)">下一页文档</button>
          <label>文档<select v-model="documentId" aria-label="交付文档"><option value="">请选择</option><option v-for="d in documentChoices" :key="d.reference.id" :value="d.reference.id">{{ d.body.name }} · {{ d.reference.version }}</option></select></label><button :disabled="busy || !documentId" @click="chooseDocument">核对并加入交付物</button><ul><li v-for="d in deliverables" :key="d.id">{{ d.id }} · {{ d.version }} <button :disabled="busy" @click="deliverables = deliverables.filter(x => x.id !== d.id)">移除此交付物</button></li></ul>
          <button :disabled="locked || !deliverables.length || work.holdState === 'HELD'" @click="submitTask">提交任务交付</button><p>没有交付物时需另有批准豁免；当前入口不签发该豁免。</p>
        </section>
      </section>
      <details v-if="current"><summary>历史原件</summary><label>版本<input v-model="historyVersion" aria-label="历史版本" pattern="[1-9][0-9]*" /></label><button :disabled="busy" @click="readHistory">读取历史原件</button><pre v-if="history">{{ history.originalJson }}</pre></details>
    </section>
  </main>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { usePermissionStore } from '@/stores/permission'
import { AUTH_EVENT, identityStamp, requireIdentity } from '@/auth/identity'
import { authenticationCanRead } from '@/auth/browserAuthentication'
import { engineeringApi, type EngineeringCreation, type EngineeringReference, type EngineeringVersion, type SourceChoice } from '@/api/plm/engineeringProducts'
import { requirementSetApi, type RequirementSetSnapshot } from '@/api/plm/requirementSet'
import { documentApi, type DocumentSnapshot } from '@/api/plm/controlledDocument'
import { engineeringIterationApi as api, iterationLabel as label, type EngineeringIterationScope, type EngineeringIterationSnapshot, type EngineeringIterationCommand, type IterationProjectInput, type IterationPlan, type IterationTaskPlan } from '@/api/plm/engineeringIteration'
import { engineeringIterationResponse as response, pendingEngineeringIteration, saveEngineeringIteration, resolveEngineeringIteration, type PendingEngineeringIteration } from '@/auth/engineeringIterationRecovery'
const permission = usePermissionStore(), can = (action: string) => permission.loaded && permission.has(`plm-engineering-iteration:${action}`)
const busy = ref(false), error = ref(''), notice = ref(''), scope = ref<EngineeringIterationScope | null>(null), pending = ref<PendingEngineeringIteration | null>(null), locked = computed(() => busy.value || !!pending.value)
const rows = ref<EngineeringIterationSnapshot[]>([]), page = ref(1), search = ref(''), project = ref<EngineeringIterationSnapshot | null>(null), iterations = ref<EngineeringIterationSnapshot[]>([]), childPage = ref(1), current = ref<EngineeringIterationSnapshot | null>(null)
const creation = ref<EngineeringCreation | null>(null), department = ref(''), objectId = ref(''), reason = ref(''), projectDraft = ref<IterationProjectInput | null>(null), plan = ref<IterationPlan | null>(null), taskDraft = ref<IterationTaskPlan | null>(null)
const origin = ref<'NEW_PRODUCT' | 'CHANGE' | 'LEGACY_REVIEW'>('NEW_PRODUCT'), noParentReason = ref(''), work = computed(() => current.value?.body.iteration || null), projectMembers = computed(() => project.value?.body.project?.definition.members || [])
const members = ref<{ id: string; name: string }[]>([]), memberSearch = ref(''), memberChoice = ref(''), siteSearch = ref(''), siteOptions = ref<SourceChoice[]>([]), productSearch = ref(''), productOptions = ref<EngineeringVersion[]>([])
const setSearch = ref(''), setPage = ref(1), setChoices = ref<RequirementSetSnapshot[]>([]), setId = ref(''), setVersion = ref(''), selectedSet = ref<RequirementSetSnapshot | null>(null)
const submitTaskId = ref(''), deliverables = ref<EngineeringReference[]>([]), documentSearch = ref(''), documentChoices = ref<DocumentSnapshot[]>([]), documentId = ref(''), documentPage = ref(1), historyVersion = ref('1'), history = ref<EngineeringIterationSnapshot | null>(null)
const reviewDocuments = ref<DocumentSnapshot[]>([])
const copy = <T,>(v: T): T => JSON.parse(JSON.stringify(v)) as T, cryptoId = () => crypto.randomUUID()
let generation = 0, live = true
function memberName(id: string) { return members.value.find(m => m.id === id)?.name || (id === scope.value?.actorId ? '当前用户' : id) }
function resetEditor() { current.value = null; creation.value = null; projectDraft.value = null; plan.value = null; taskDraft.value = null; objectId.value = ''; reason.value = department.value = ''; selectedSet.value = null; setChoices.value = []; setId.value = setVersion.value = ''; submitTaskId.value = ''; deliverables.value = []; documentChoices.value = []; reviewDocuments.value = []; documentId.value = ''; history.value = null; siteOptions.value = []; productOptions.value = [] }
function clearPrivate() { resetEditor(); project.value = null; iterations.value = []; rows.value = []; members.value = []; scope.value = null; pending.value = null; notice.value = '' }
async function run(action: (check: () => void) => Promise<void>) {
  if (busy.value) return
  const stamp = identityStamp(), epoch = generation
  const check = () => { requireIdentity(stamp); if (!live || epoch !== generation || !authenticationCanRead()) throw new Error('身份已变化，请重新载入。') }
  busy.value = true; error.value = notice.value = ''
  try { check(); await action(check); check() }
  catch (e: any) { try { check(); if (e?.response?.status === 403) clearPrivate(); const message = e?.response?.data?.message || e?.message || ''; error.value = /^[A-Z][A-Z0-9_]+$/.test(message) ? '无法完成，请核对当前权限、准确来源、状态与版本。' : message || '暂时无法完成。' } catch { /* Discard obsolete responses. */ } }
  finally { try { check(); pending.value = scope.value ? pendingEngineeringIteration(scope.value) : null; busy.value = false } catch { if (live && epoch === generation) busy.value = false } }
