async function reload() { await run(async check => { clearPrivate(); if (!permission.loaded) await permission.loadMyActions(); check(); if (!can('query')) throw new Error('当前无权读取工程项目。'); const s = response(await api.scope()); check(); scope.value = s; const r = response(await api.list('PROJECT', undefined, search.value, page.value)); check(); rows.value = r }) }
async function list(p: number) { await run(async check => { rows.value = []; const r = response(await api.list('PROJECT', undefined, search.value, p)); check(); rows.value = r; page.value = p }) }
async function children(p: number) { await run(async check => { if (!project.value) return; iterations.value = []; const r = response(await api.list('ITERATION', project.value.reference.id, '', p)); check(); iterations.value = r; childPage.value = p }) }
async function select(value: EngineeringIterationSnapshot, check: () => void) {
  resetEditor(); current.value = value; objectId.value = value.reference.id
  if (value.body.project) { project.value = value; projectDraft.value = copy(value.body.project.definition); const r = response(await api.list('ITERATION', value.reference.id)); check(); iterations.value = r; childPage.value = 1 }
  else if (value.body.iteration) { const p = response(await api.read(value.body.iteration.projectId)); check(); project.value = p; plan.value = copy(value.body.iteration.plan) }
  if (projectDraft.value?.site) siteOptions.value = [{ reference: projectDraft.value.site, code: '已采用场地' }]
  if (projectDraft.value?.product) productOptions.value = [{ reference: projectDraft.value.product, product: { name: '已采用工程产品' } } as EngineeringVersion]
}
async function open(id: string) { await run(async check => { resetEditor(); const value = response(await api.read(id)); check(); await select(value, check) }) }
async function newProject() { await run(async check => { resetEditor(); project.value = null; iterations.value = []; const context = response(await api.creationContext()); check(); if (context.tenantId !== scope.value?.tenantId || context.actorId !== scope.value?.actorId) throw new Error('当前身份已变化。'); creation.value = context; objectId.value = cryptoId(); projectDraft.value = { name: '', ownerId: context.actorId, members: [context.actorId], site: null, product: null, objective: '', startDate: null, endDate: null, milestones: [] } }) }
function newIteration() { if (!project.value || !scope.value || locked.value) return; resetEditor(); objectId.value = cryptoId(); plan.value = { name: '', ownerId: scope.value.actorId, goal: '', startDate: '', endDate: '' }; origin.value = 'NEW_PRODUCT'; noParentReason.value = '' }
async function write(action: string, fields: Partial<EngineeringIterationCommand> = {}) { await run(async check => { if (!scope.value || pending.value) return; if (!reason.value.trim()) throw new Error('请填写本次操作原因。'); const id = objectId.value, command: Omit<EngineeringIterationCommand, 'operationId'> = { objectId: id, action, expectedVersion: current.value?.reference.version ?? null, expectedEtag: current.value?.etag ?? null, reason: reason.value, ...copy(fields) }; const saved = await saveEngineeringIteration(scope.value, id, check, operationId => api.save({ ...command, operationId })); check(); if (saved.result) { const value = response(await api.read(saved.result.objectId)); check(); await select(value, check); notice.value = '已保存并核对原操作结果。' } }) }
const command = write
function saveProject() { if (!projectDraft.value) return; const p = copy(projectDraft.value); p.startDate ||= null; p.endDate ||= null; return write(current.value ? 'EDIT_PROJECT' : 'CREATE_PROJECT', { project: p, expectedAuthorityVersion: creation.value?.authorityVersion ?? null, departmentId: creation.value ? department.value || null : null }) }
function savePlan() { if (!plan.value || !project.value) return; if (current.value) return write('EDIT_PLAN', { plan: plan.value }); if (!selectedSet.value || origin.value !== 'NEW_PRODUCT') return; return write('CREATE_ITERATION', { projectId: project.value.reference.id, plan: plan.value, origin: { type: origin.value, noParentReason: noParentReason.value }, requirementSet: selectedSet.value.reference }) }
function replaceInputs() { if (selectedSet.value) return write('REPLACE_INPUTS', { requirementSet: selectedSet.value.reference }) }
function newTask() { if (!scope.value || locked.value) return; taskDraft.value = { id: cryptoId(), title: '', ownerId: scope.value.actorId, confirmerId: '', weight: '', dueDate: '', acceptance: '' } }
function saveTask() { if (taskDraft.value) return write('SAVE_TASK', { task: taskDraft.value }) }
function submitTask() { return write('SUBMIT_TASK', { taskId: submitTaskId.value, deliverables: deliverables.value }) }
async function recover(close: boolean) { await run(async check => { if (!scope.value) return; const value = await resolveEngineeringIteration(scope.value, close, check); check(); if (value.result) { const v = response(await api.read(value.result.objectId)); check(); await select(v, check) } notice.value = value.state === 'UNKNOWN' ? '原结果仍未确认，请保留记录。' : '原操作已确认。' }) }
async function findMembers() { await run(async check => { const found = response(await api.members(memberSearch.value)); check(); members.value = [...members.value.filter(m => !found.some(x => x.id === m.id)), ...found] }) }
function addMember() { if (projectDraft.value && members.value.some(m => m.id === memberChoice.value) && !projectDraft.value.members.includes(memberChoice.value)) projectDraft.value.members.push(memberChoice.value); memberChoice.value = '' }
async function findSites() { await run(async check => { const r = response(await api.sites(siteSearch.value)); check(); const saved = projectDraft.value?.site; siteOptions.value = saved && !r.some(x => x.reference.id === saved.id && x.reference.version === saved.version) ? [{ reference: saved, code: '已采用场地' }, ...r] : r }) }
async function findProducts() { await run(async check => { const r = response(await engineeringApi.list(productSearch.value)); check(); const saved = projectDraft.value?.product; productOptions.value = saved && !r.some(x => x.reference.id === saved.id && x.reference.version === saved.version) ? [{ reference: saved, product: { name: '已采用工程产品' } } as EngineeringVersion, ...r] : r }) }
async function findSets(p: number) { await run(async check => { setChoices.value = []; setId.value = ''; const r = response(await requirementSetApi.list(setSearch.value, p)); check(); setChoices.value = r; setPage.value = p }) }
async function chooseSet() { await run(async check => { selectedSet.value = null; if (!setChoices.value.some(s => s.reference.id === setId.value)) return; const value = response(await requirementSetApi.read(setId.value, setVersion.value || undefined)); check(); if (value.state !== 'APPROVED' || value.missing.length) throw new Error('此准确需求集尚未完成批准或其来源已不可用。'); selectedSet.value = value }) }
async function findDocuments(p: number) { await run(async check => { documentChoices.value = []; documentId.value = ''; const r = response(await documentApi.list(undefined, documentSearch.value, p)); check(); documentChoices.value = r; documentPage.value = p }) }
async function chooseDocument() { await run(async check => { const row = documentChoices.value.find(d => d.reference.id === documentId.value); if (!row) return; const value = response(await documentApi.read(row.reference.id, row.reference.version)); check(); if (!value.contentStatus.length || value.contentStatus.some(x => x.availability !== 'AVAILABLE')) throw new Error('该准确文档的文件当前不可用。'); deliverables.value = deliverables.value.filter(d => d.id !== value.reference.id).concat(value.reference); documentId.value = '' }) }
async function inspectDeliverables(refs: EngineeringReference[]) { await run(async check => { reviewDocuments.value = []; const originals: DocumentSnapshot[] = []; for (const ref of refs) { const v = response(await documentApi.read(ref.id, ref.version)); check(); if (v.reference.owner !== ref.owner || v.reference.id !== ref.id || v.reference.version !== ref.version || v.reference.digest !== ref.digest) throw new Error('交付原件与准确引用不一致。'); originals.push(v) } reviewDocuments.value = originals }) }
async function download(d: DocumentSnapshot, occurrence: string) { await run(async check => { const blob = await documentApi.download(d.reference.id, d.reference.version, occurrence); check(); const url = URL.createObjectURL(blob), link = document.createElement('a'); link.href = url; link.download = d.contentStatus.find(x => x.occurrenceId === occurrence)?.fileName || '交付原件'; link.click(); URL.revokeObjectURL(url) }) }
async function readHistory() { await run(async check => { if (!current.value) return; history.value = null; const value = response(await api.read(current.value.reference.id, historyVersion.value)); check(); history.value = value }) }
function invalidate() { generation++; busy.value = false; error.value = ''; clearPrivate() }
watch(() => [permission.loaded, can('query')], () => { if (!can('query')) invalidate() })
onMounted(() => { window.addEventListener(AUTH_EVENT, invalidate); void reload() })
onBeforeUnmount(() => { live = false; generation++; window.removeEventListener(AUTH_EVENT, invalidate) })
</script>
<style scoped>
.iterations{max-width:1200px;margin:auto;padding:24px;color:var(--el-text-color-primary,#253047)}header{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}section,article{border:1px solid var(--el-border-color,#d8dce3);border-radius:8px;padding:18px;margin:18px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}label{display:flex;flex-direction:column;gap:6px;margin:10px 0}input,textarea,select,button{font:inherit;padding:8px;border:1px solid var(--el-border-color,#c4cbd6);border-radius:5px}textarea{min-height:70px}button{cursor:pointer;margin:5px}button:disabled{cursor:default;opacity:.55}fieldset{border:0;padding:0;min-width:0}table{width:100%;text-align:left;border-collapse:collapse}th,td{border-bottom:1px solid #d8dce3;padding:10px}pre{white-space:pre-wrap;overflow-wrap:anywhere}p,li{overflow-wrap:anywhere}[role=alert]{color:#b42318}[role=status]{color:#167044}@media(max-width:640px){.iterations{padding:12px}section,article{padding:12px}.grid{grid-template-columns:1fr}}
</style>
